int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    spin_lock_init(&dev->slock);

    ret = airspy_usb_ctrl_msg(dev, 0, 0, 0, 0);
    if (ret < 0)
        goto error_free_dev;

    ret = videobuf2_queue_init(&dev->vb2_queue, &airspy_queue_ops,
                               &intf->dev, &dev->lock, V4L2_BUF_TYPE_VIDEO_CAPTURE,
                               V4L2_FIELD_NONE, sizeof(struct airspy_buffer),
                               NULL, NULL);
    if (ret < 0)
        goto error_free_dev;

    dev->vdev = video_device_alloc();
    if (!dev->vdev) {
        ret = -ENOMEM;
        goto error_free_dev;
    }

    strscpy(dev->vdev->name, "Airspy", sizeof(dev->vdev->name));
    dev->vdev->fops = &airspy_fops;
    dev->vdev->ioctl_ops = &airspy_ioctl_ops;
    dev->vdev->release = video_device_release;
    dev->vdev->v4l2_dev = &dev->v4l2_dev;

    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto error_free_video_dev;

    ret = video_register_device(dev->vdev, VFL_TYPE_VIDEO, 0);
    if (ret < 0)
        goto error_unregister_v4l2;

    ret = v4l2_ctrl_handler_setup(&dev->ctrl_handler);
    if (ret < 0)
        goto error_unreg_video_dev;

    dev_info(&intf->dev, "Airspy device registered\n");
    dev_info(&intf->dev, "This is an experimental SDR API\n");

    usb_set_intfdata(intf, dev);
    return 0;

error_unreg_video_dev:
    video_unregister_device(dev->vdev);
error_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
error_free_video_dev:
    video_device_release(dev->vdev);
error_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    spin_lock_init(&dev->irq_lock);

    ret = airspy_usb_init_device(dev, intf);
    if (ret < 0)
        goto err_free_dev;

    ret = videobuf2_queue_alloc(&dev->vb2_queue, &airspy_queue_ops, &dev->video_dev, &dev->lock,
                                V4L2_BUF_TYPE_VIDEO_CAPTURE, sizeof(struct airspy_buffer), NULL);
    if (ret < 0)
        goto err_cleanup_device;

    ret = video_register_device(&dev->video_dev, VFL_TYPE_VIDEO, 0);
    if (ret < 0)
        goto err_free_vb2_queue;

    v4l2_device_register(&dev->udev->dev, &dev->v4l2_dev);

    v4l2_ctrl_handler_init(&dev->ctrl_handler, 8);
    dev->gain_ctrl = v4l2_ctrl_new_std(&dev->ctrl_handler, &airspy_ctrl_ops,
                                       V4L2_CID_GAIN, 0, 255, 1, 0);
    if (dev->ctrl_handler.error)
        goto err_unregister_v4l2;

    dev->video_dev.ctrl_handler = &dev->ctrl_handler;

    dev_dbg(&dev->udev->dev, "Airspy device probed successfully.");
    pr_info("Airspy SDR: This is an experimental API, expect changes in future versions.");

    usb_set_intfdata(intf, dev);
    return 0;

err_unregister_v4l2:
    v4l2_device_unregister(&dev->v4l2_dev);
err_free_vb2_queue:
    videobuf2_queue_free(&dev->vb2_queue);
err_cleanup_device:
    airspy_usb_cleanup_device(dev);
err_free_dev:
    kfree(dev);
    return ret;
}

int airspy_usb_probe(struct usb_interface *intf, const struct usb_device_id *id)
{
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    mutex_init(&dev->buf_lock);
    init_waitqueue_head(&dev->wait);

    ret = airspy_detect(dev, intf);
    if (ret < 0)
        goto error_free_dev;

    ret = airspy_init_device(dev);
    if (ret < 0)
        goto error_free_dev;

    ret = videobuf2_queue_alloc(&dev->vb_queue, V4L2_BUF_TYPE_VIDEO_CAPTURE, NULL,
                                V4L2_MEMORY_MMAP, sizeof(struct airspy_buffer));
    if (ret < 0)
        goto error_cleanup_device;

    ret = video_register_device(&dev->vdev, VFL_TYPE_VIDEO, 0, 0);
    if (ret < 0)
        goto error_free_video;

    v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    dev->vdev.v4l2_dev = &dev->v4l2_dev;

    ret = v4l2_ctrl_handler_setup(&dev->ctrl_handler);
    if (ret < 0)
        goto error_unregister_video;

    dev_info(&intf->dev, "Airspy device registered as %s\n", video_device_node_name(&dev->vdev));
    dev_info(&intf->dev, "Using experimental SDR API\n");

    usb_set_intfdata(intf, dev);
    return 0;

error_unregister_video:
    video_unregister_device(&dev->vdev);
error_free_video:
    videobuf2_queue_free(&dev->vb_queue);
error_cleanup_device:
    airspy_cleanup_device(dev);
error_free_dev:
    kfree(dev);
    return ret;
}

int airspy_probe(struct usb_interface *intf, const struct usb_device_id *id) {
    struct airspy_dev *dev;
    int ret;

    dev = kzalloc(sizeof(*dev), GFP_KERNEL);
    if (!dev)
        return -ENOMEM;

    mutex_init(&dev->lock);
    mutex_init(&dev->buf_lock);

    ret = airspy_ctrl_msg(dev, AIRSPY_REQUEST_GET_FIRMWARE_VERSION, NULL, 0);
    if (ret < 0)
        goto error_cleanup;

    ret = video_buffer_queue_init(&dev->vbq);
    if (ret < 0)
        goto error_cleanup;

    strlcpy(dev->vdev.name, "Airspy SDR", sizeof(dev->vdev.name));
    dev->vdev.vfl_dir = VFL_DIR_RX;
    dev->vdev.release = video_device_release;
    dev->vdev.fops = &airspy_fops;
    dev->vdev.ioctl_ops = &airspy_ioctl_ops;
    dev->vdev.queue = &dev->vbq;

    ret = video_register_device(&dev->vdev, VFL_TYPE_VIDEO, -1);
    if (ret < 0)
        goto error_cleanup;

    dev->v4l2_dev.name = "airspy";
    ret = v4l2_device_register(&intf->dev, &dev->v4l2_dev);
    if (ret < 0)
        goto error_unregister;

    v4l2_ctrl_handler_init(&dev->ctrl_hdl, 8);
    dev->ctrl_hdl.lock = &dev->lock;
    dev->gain_ctrl = v4l2_ctrl_new_std(&dev->ctrl_hdl, NULL, V4L2_CID_GAIN, 0, 100, 1, 0);
    if (dev->ctrl_hdl.error) {
        ret = dev->ctrl_hdl.error;
        goto error_unregister;
    }

    dev->vdev.ctrl_handler = &dev->ctrl_hdl;

    dev_info(&intf->dev, "New device registered (experimental SDR API)");
    return 0;

error_unregister:
    video_unregister_device(&dev->vdev);
error_cleanup:
    kfree(dev);
    return ret;
}

